WITH exploded AS (SELECT id, plan, effective_from, EXPLODE_OUTER(tier_limits) AS val FROM price_tiers), cleaned AS (SELECT *, CASE WHEN plan = 'starter' THEN 1 ELSE 0 END AS is_starter FROM exploded WHERE effective_from >= DATE '2024-02-16'), cleaned_price_tiers AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title FROM cleaned WHERE plan = 'starter'), filtered AS (SELECT id, effective_from, val, is_starter, COALESCE(is_starter, 0) AS is_starter_filled, CASE WHEN plan IN ('basic', 'starter') THEN 'Priority' ELSE 'Other' END AS plan_group FROM cleaned_price_tiers WHERE MONTH(effective_from) IN (4, 8, 12)) SELECT id, effective_from, val, plan_group FROM filtered ORDER BY effective_from DESC NULLS FIRST
